:6:\"banner\";}s:13:\"keyword_slugs\";a:2:{i:0;s:4:\"core\";i:1;s:8:\"featured\";}s:15:\"pattern_content\";s:869:\"<!-- wp:media-text {\"align\":\"full\",\"mediaType\":\"image\",\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text alignfull is-stacked-on-mobile is-vertically-aligned-center\"><figure class=\"wp-block-media-text__media\"><img alt=\"Zbliżenie, abstrakcyjny widok na architekturę.\" src=\"https://s.w.org/images/core/5.8/architecture-04.jpg\"></figure><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"color\":{\"text\":\"#000000\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center has-text-color\" style=\"color:#000000\"><strong>Otwarte przestrzenie</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"extra-small\"} -->\n<p class=\"has-text-align-center has-extra-small-font-size\"><a href=\"#\">Zobacz przypadek użycia ↗</a></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\";}i:39;O:8:\"stdClass\":7:{s:2:\"id\";i:2135;s:5:\"title\";O:8:\"stdClass\":1:{s:8:\"rendered\";s:40:\"Duży nagłówek z tekstem i przyciskiem\";}s:7:\"content\";O:8:\"stdClass\":2:{s:8:\"rendered\";s:1571:\"\n<div class=\"wp-block-cover alignfull has-parallax\" style=\"min-height:100vh;aspect-ratio:unset;\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-40 has-background-dim\" style=\"background-color:#000000\"></span><div class=\"wp-block-cover__image-background has-parallax\" role=\"img\" style=\"background-position:50% 50%;background-image:url(https://s.w.org/images/core/5.8/art-01.jpg)\"></div><div class=\"wp-block-cover__inner-container is-layout-flow wp-block-cover-is-layout-flow\">\n<h2 class=\"wp-block-heading alignwide has-white-color has-text-color\" style=\"font-size:48px;line-height:1.2\"><strong><em>Za granicą:</em></strong><br><strong><em>1500 — 1960</em></strong></h2>\n\n\n\n<div class=\"wp-block-columns alignwide is-layout-flex wp-container-core-columns-is-layout-0e47273b wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:60%\">\n<p class=\"has-text-color wp-block-paragraph\" style=\"color:#ffffff\">Wystawa poświęcona różnym wyobrażeniom oceanu na przestrzeni dziejów, od XVI do XX wieku. Odbywa się w naszym Open Room na <em>Piętrze 2</em>.</p>\n\n\n\n<div class=\"wp-block-buttons is-layout-flex wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button is-style-outline is-style-outline--21\"><a class=\"wp-block-button__link has-text-color has-background wp-element-button\" style=\"color:#ffffff;background-color:#000000\">wizyta</a></div>\n</div>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\"></div>\n</div>\n</div></div>\n\";s:9:\"protected\";b:0;}s:4:\"meta\";O:8:\"stdClass\":8:{s:13:\"wpop_keywords\";s:0:\"\";s:16:\"wpop_description\";s:68:\"Duży nagłówek z obrazkiem tła i tekstem oraz przycisk na górze.\";s:19:\"wpop_viewport_width\";i:1200;s:16:\"wpop_block_types\";a:1:{i:0;s:0:\"\";}s:11:\"wpop_locale\";s:5:\"pl_PL\";s:15:\"wpop_wp_version\";s:0:\"\";s:25:\"wpop_contains_block_types\";s:88:\"core/button,core/buttons,core/column,core/columns,core/cover,core/heading,core/paragraph\";s:9:\"footnotes\";s:0:\"\";}s:14:\"category_slugs\";a:1:{i:0;s:6:\"banner\";}s:13:\"keyword_slugs\";a:2:{i:0;s:4:\"core\";i:1;s:8:\"featured\";}s:15:\"pattern_content\";s:2028:\"<!-- wp:cover {\"url\":\"https://s.w.org/images/core/5.8/art-01.jpg\",\"hasParallax\":true,\"dimRatio\":40,\"customOverlayColor\":\"#000000\",\"minHeight\":100,\"minHeightUnit\":\"vh\",\"contentPosition\":\"center center\",\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull has-parallax\" style=\"min-height:100vh\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-40 has-background-dim\" style=\"background-color:#000000\"></span><div class=\"wp-block-cover__image-background has-parallax\" role=\"img\" style=\"background-position:50% 50%;background-image:url(https://s.w.org/images/core/5.8/art-01.jpg)\"></div><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"48px\",\"lineHeight\":\"1.2\"}},\"className\":\"alignwide has-white-color has-text-color\"} -->\n<h2 class=\"wp-block-heading alignwide has-white-color has-text-color\" style=\"font-size:48px;line-height:1.2\"><strong><em>Za granicą:</em></strong><br><strong><em>1500 — 1960</em></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"width\":\"60%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:60%\"><!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#ffffff\"}}} -->\n<p class=\"has-text-color\" style=\"color:#ffffff\">Wystawa poświęcona różnym wyobrażeniom oceanu na przestrzeni dziejów, od XVI do XX wieku. Odbywa się w naszym Open Room na <em>Piętrze 2</em>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"color\":{\"text\":\"#ffffff\",\"background\":\"#000000\"}},\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link has-text-color has-background wp-element-button\" style=\"color:#ffffff;background-color:#000000\">wizyta</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover -->\";}i:40;O:8:\"stdClass\":7:{s:2:\"id\";i:2481;s:5:\"title\";O:8:\"stdClass\":1:{s:8:\"rendered\";s:47:\"Duży nagłówek z tekstem wyrównanym do lewej\";}s:7:\"content\";O:8:\"stdClass\":2:{s:8:\"rendered\";s:1406:\"\n<div class=\"wp-block-cover alignfull\" style=\"min-height:800px;aspect-ratio:unset;\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-60 has-background-dim\"></span><img decoding=\"async\" alt=\"\" class=\"wp-block-cover__image-background\" data-object-fit=\"cover\" src=\"https://s.w.org/images/core/5.8/forest.jpg\"><div class=\"wp-block-cover__inner-container is-layout-flow wp-block-cover-is-layout-flow\">\n<h2 class=\"wp-block-heading alignwide has-text-color\" style=\"color:#ffe074;font-size:64px\">Las.</h2>\n\n\n\n<div class=\"wp-block-columns alignwide is-layout-flex wp-container-core-columns-is-layout-0e47273b wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:55%\">\n<div aria-hidden=\"true\" class=\"wp-block-spacer\" style=\"height:330px\"></div>\n\n\n\n<p class=\"has-text-color wp-block-paragraph\" style=\"color:#ffe074;font-size:12px;line-height:1.3\"><em>Nawet dziecko wie, jak cenny jest las. Świeży, zapierający dech w piersiach zapach drzew. Echo ptaków latających nad tą gęstą wielkością. Stabilny klimat, zrównoważone, różnorodne życie i źródło kultury. A jednak, lasy i inne ekosystemy wiszą na włosku, zagrożone przekształceniem w pola uprawne, pastwiska i plantacje.</em></p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\"></div>\n</div>\n</div></div>\n\";s:9:\"protected\";b:0;}s:4:\"meta\";O:8:\"stdClass\":8:{s:13:\"wpop_keywords\";s:0:\"\";s:16:\"wpop_description\";s:40:\"Zdjęcie na okładce z cytatem na górze\";s:19:\"wpop_viewport_width\";i:1200;s:16:\"wpop_block_types\";a:1:{i:0;s:0:\"\";}s:11:\"wpop_locale\";s:5:\"pl_PL\";s:15:\"wpop_wp_version\";s:0:\"\";s:25:\"wpop_contains_block_types\";s:75:\"core/column,core/columns,core/cover,core/heading,core/paragraph,core/spacer\";s:9:\"footnotes\";s:0:\"\";}s:14:\"category_slugs\";a:1:{i:0;s:6:\"banner\";}s:13:\"keyword_slugs\";a:2:{i:0;s:4:\"core\";i:1;s:8:\"featured\";}s:15:\"pattern_content\";s:1716:\"<!-- wp:cover {\"url\":\"https://s.w.org/images/core/5.8/forest.jpg\",\"dimRatio\":60,\"minHeight\":800,\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull\" style=\"min-height:800px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-60 has-background-dim\"></span><img alt=\"\" class=\"wp-block-cover__image-background\" data-object-fit=\"cover\" src=\"https://s.w.org/images/core/5.8/forest.jpg\"><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"align\":\"wide\",\"style\":{\"color\":{\"text\":\"#ffe074\"},\"typography\":{\"fontSize\":\"64px\"}}} -->\n<h2 class=\"wp-block-heading alignwide has-text-color\" style=\"color:#ffe074;font-size:64px\">Las.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"width\":\"55%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:55%\"><!-- wp:spacer {\"height\":\"330px\"} -->\n<div aria-hidden=\"true\" class=\"wp-block-spacer\" style=\"height:330px\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#ffe074\"},\"typography\":{\"lineHeight\":\"1.3\",\"fontSize\":\"12px\"}}} -->\n<p class=\"has-text-color\" style=\"color:#ffe074;font-size:12px;line-height:1.3\"><em>Nawet dziecko wie, jak cenny jest las. Świeży, zapierający dech w piersiach zapach drzew. Echo ptaków latających nad tą gęstą wielkością. Stabilny klimat, zrównoważone, różnorodne życie i źródło kultury. A jednak, lasy i inne ekosystemy wiszą na włosku, zagrożone przekształceniem w pola uprawne, pastwiska i plantacje.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover -->\";}i:41;O:8:\"stdClass\":7:{s:2:\"id\";i:2210;s:5:\"title\";O:8:\"stdClass\":1:{s:8:\"rendered\";s:10:\"nagłówek\";}s:7:\"content\";O:8:\"stdClass\":2:{s:8:\"rendered\";s:528:\"\n<h2 class=\"alignwide wp-block-heading\" id=\"we-re-a-studio-in-berlin-with-an-international-practice-in-architecture-urban-planning-and-interior-design-we-believe-in-sharing-knowledge-and-promoting-dialogue-to-increase-the-creative-potential-of-collaboration\" style=\"font-size:48px;line-height:1.1\">Jesteśmy studiem w Berlinie z międzynarodową doświadczeniem w architekturze, urbanistyce i projektowaniu wnętrz. Wierzymy w dzielenie się wiedzą i promowanie dialogu, aby zwiększyć kreatywny potencjał współpracy.</h2>\n\";s:9:\"protected\";b:0;}s:4:\"meta\";O:8:\"stdClass\":8:{s:13:\"wpop_keywords\";s:19:\"duży tekst, TYTUŁ\";s:16:\"wpop_description\";s:16:\"Tekst nagłówka\";s:19:\"wpop_viewport_width\";i:1200;s:16:\"wpop_block_types\";a:1:{i:0;s:12:\"core/heading\";}s:11:\"wpop_locale\";s:5:\"pl_PL\";s:15:\"wpop_wp_version\";s:0:\"\";s:25:\"wpop_contains_block_types\";s:12:\"core/heading\";s:9:\"footnotes\";s:0:\"\";}s:14:\"category_slugs\";a:1:{i:0;s:4:\"text\";}s:13:\"keyword_slugs\";a:2:{i:0;s:4:\"core\";i:1;s:8:\"featured\";}s:15:\"pattern_content\";s:629:\"<!-- wp:heading {\"align\":\"wide\",\"style\":{\"typography\":{\"fontSize\":\"48px\",\"lineHeight\":\"1.1\"}}} -->\n<h2 class=\"alignwide\" id=\"we-re-a-studio-in-berlin-with-an-international-practice-in-architecture-urban-planning-and-interior-design-we-believe-in-sharing-knowledge-and-promoting-dialogue-to-increase-the-creative-potential-of-collaboration\" style=\"font-size:48px;line-height:1.1\">Jesteśmy studiem w Berlinie z międzynarodową doświadczeniem w architekturze, urbanistyce i projektowaniu wnętrz. Wierzymy w dzielenie się wiedzą i promowanie dialogu, aby zwiększyć kreatywny potencjał współpracy.</h2>\n<!-- /wp:heading -->\";}i:42;O:8:\"stdClass\":7:{s:2:\"id\";i:2149;s:5:\"title\";O:8:\"stdClass\":1:{s:8:\"rendered\";s:28:\"Dwie kolumny tekstu i tytuł\";}s:7:\"content\";O:8:\"stdClass\":2:{s:8:\"rendered\";s:1603:\"\n<h2 class=\"wp-block-heading\" style=\"font-size:38px;line-height:1.4\"><strong>Podróż rozpoczęła się szczęśliwie, przy błękitnym niebie i spokojnym morzu.</strong></h2>\n\n\n\n<div class=\"wp-block-columns is-layout-flex wp-container-core-columns-is-layout-0e47273b wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<p class=\"wp-block-paragraph\" style=\"font-size:18px\">Weszli za nią na pokład. Dym i domy zniknęły, a statek znajdował się na szerokiej przestrzeni morza, bardzo świeżego i czystego, choć bladego we wczesnym świetle. Zostawili zabłocony Londyn. Bardzo cienka linia cienia zwężała się na horyzoncie, ledwie na tyle gruba, by wytrzymać ciężar Paryża, który jednak na niej spoczywał. Byli wolni od dróg, wolni od ludzi, i ta sama radość z wolności ogarnęła ich wszystkich.</p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<p class=\"wp-block-paragraph\" style=\"font-size:18px\">Statek pewnie przedzierał się przez drobne fale, które uderzały w niego, a potem syczały jak musująca woda, pozostawiając po obu stronach cienką warstwę bąbelków i piany. Bezbarwne październikowe niebo nad nami było lekko zachmurzone, jakby smugą dymu z ogniska, a powietrze było cudownie słone i rześkie. W istocie było zbyt zimno, by stać w miejscu. Pani Ambrose objęła męża ramieniem, a gdy odchodzili, po sposobie, w jaki jej pochylony policzek zwrócił się ku jego policzkowi, można było poznać, że ma do przekazania coś prywatnego.</p>\n</div>\n</div>\n\";s:9:\"protected\";b:0;}s:4:\"meta\";O:8:\"stdClass\":8:{s:13:\"wpop_keywords\";s:0:\"\";s:16:\"wpop_description\";s:53:\"Dwie kolumny tekstu poprzedzone długim nagłówkiem.\";s:19:\"wpop_viewport_width\";i:1200;s:16:\"wpop_block_types\";a:1:{i:0;s:0:\"\";}s:11:\"wpop_locale\";s:5:\"pl_PL\";s:15:\"wpop_wp_version\";s:0:\"\";s:25:\"wpop_contains_block_types\";s:52:\"core/column,core/columns,core/heading,core/paragraph\";s:9:\"footnotes\";s:0:\"\";}s:14:\"category_slugs\";a:2:{i:0;s:7:\"columns\";i:1;s:4:\"text\";}s:13:\"keyword_slugs\";a:2:{i:0;s:4:\"core\";i:1;s:8:\"featured\";}s:15:\"pattern_content\";s:1720:\"<!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":38,\"lineHeight\":\"1.4\"}}} -->\n<h2 style=\"font-size:38px;line-height:1.4\"><strong>Podróż rozpoczęła się szczęśliwie, przy błękitnym niebie i spokojnym morzu.</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":18}}} -->\n<p style=\"font-size:18px\">Weszli za nią na pokład. Dym i domy zniknęły, a statek znajdował się na szerokiej przestrzeni morza, bardzo świeżego i czystego, choć bladego we wczesnym świetle. Zostawili zabłocony Londyn. Bardzo cienka linia cienia zwężała się na horyzoncie, ledwie na tyle gruba, by wytrzymać ciężar Paryża, który jednak na niej spoczywał. Byli wolni od dróg, wolni od ludzi, i ta sama radość z wolności ogarnęła ich wszystkich.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":18}}} -->\n<p style=\"font-size:18px\">Statek pewnie przedzierał się przez drobne fale, które uderzały w niego, a potem syczały jak musująca woda, pozostawiając po obu stronach cienką warstwę bąbelków i piany. Bezbarwne październikowe niebo nad nami było lekko zachmurzone, jakby smugą dymu z ogniska, a powietrze było cudownie słone i rześkie. W istocie było zbyt zimno, by stać w miejscu. Pani Ambrose objęła męża ramieniem, a gdy odchodzili, po sposobie, w jaki jej pochylony policzek zwrócił się ku jego policzkowi, można było poznać, że ma do przekazania coś prywatnego.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\";}i:43;O:8:\"stdClass\":7:{s:2:\"id\";i:2151;s:5:\"title\";O:8:\"stdClass\":1:{s:8:\"rendered\";s:23:\"Dwa obrazki obok siebie\";}s:7:\"content\";O:8:\"stdClass\":2:{s:8:\"rendered\";s:567:\"\n<figure class=\"wp-block-gallery alignwide has-nested-images columns-default is-cropped wp-block-gallery-22 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" alt=\"Widok z lotu ptaka na fale rozbijające się o brzeg.\" src=\"https://s.w.org/images/core/5.8/nature-above-01.jpg\"></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" alt=\"Widok z lotu ptaka na pole. Droga biegnie przez prawy górny róg.\" src=\"https://s.w.org/images/core/5.8/nature-above-02.jpg\"></figure>\n</figure>\n\";s:9:\"protected\";b:0;}s:4:\"meta\";O:8:\"stdClass\":8:{s:13:\"wpop_keywords\";s:0:\"\";s:16:\"wpop_description\";s:49:\"Galeria obrazów z dwoma przykładowymi obrazami.\";s:19:\"wpop_viewport_width\";i:800;s:16:\"wpop_block_types\";a:1:{i:0;s:0:\"\";}s:11:\"wpop_locale\";s:5:\"pl_PL\";s:15:\"wpop_wp_version\";s:0:\"\";s:25:\"wpop_contains_block_types\";s:23:\"core/gallery,core/image\";s:9:\"footnotes\";s:0:\"\";}s:14:\"category_slugs\";a:1:{i:0;s:7:\"gallery\";}s:13:\"keyword_slugs\";a:2:{i:0;s:4:\"core\";i:1;s:8:\"featured\";}s:15:\"pattern_content\";s:700:\"<!-- wp:gallery {\"linkTo\":\"none\",\"align\":\"wide\"} -->\n<figure class=\"wp-block-gallery alignwide has-nested-images columns-default is-cropped\"><!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img alt=\"Widok z lotu ptaka na fale rozbijające się o brzeg.\" src=\"https://s.w.org/images/core/5.8/nature-above-01.jpg\"></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img alt=\"Widok z lotu ptaka na pole. Droga biegnie przez prawy górny róg.\" src=\"https://s.w.org/images/core/5.8/nature-above-02.jpg\"></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->\";}}','off'),
